if (canvas.tokens.controlled.length === 0) {
  ui.notifications.warn("Please select at least one token first!");
} else {
  for (let token of canvas.tokens.controlled) {
    const currentDim = token.document.light.dim;

    if (currentDim === 0) {
      await token.document.update({
        light: {
          bright: 5,
          dim: 30,
          angle: 360,
          color: "#ffa733",
          alpha: 0.5,
          animation: {
            type: "sunburst",
            speed: 0.5,
            intensity: 1
          }
        }
      });
      ui.notifications.info(`Activated sunlight for ${token.name}`);
    }
    else {
      await token.document.update({
        light: {
          bright: 0,
          dim: 0,
          angle: 360,
          color: null,
          alpha: 0.5,
          animation: {
            type: null,
            speed: null,
            intensity: null
          }
        }
      });
      ui.notifications.info(`Deactivated sunlight for ${token.name}`);
    }
  }
}
